input.script:
return {
  url: window.location.href,
  title: document.title,
  hasIframe: document.querySelectorAll('iframe').length,
  iframes: Array.from(document.querySelectorAll('iframe')).map(f => ({src: f.src, id: f.id, name: f.name}))
};

const iframes = document.querySelectorAll('iframe');
const results = [];
for (const iframe of iframes) {
  try {
    const doc = iframe.contentDocument || iframe.contentWindow.document;
    const inputs = doc.querySelectorAll('input');
    for (const input of inputs) {
      results.push({type: input.type, name: input.name, id: input.id, ariaLabel: input.getAttribute('aria-label')});
      if (input.type === 'checkbox') {
        input.click();
        results.push('Clicked checkbox');
      }
    }
  } catch (e) {
    results.push({error: e.message});
  }
}
return {iframeCount: iframes.length, results};

const checkboxes = document.querySelectorAll('input[type="checkbox"]');
const results = [];
for (const cb of checkboxes) {
  results.push({ariaLabel: cb.getAttribute('aria-label'), id: cb.id, name: cb.name, outerHTML: cb.outerHTML.substring(0, 200)});
  if (cb.getAttribute('aria-label') && cb.getAttribute('aria-label').includes('真人')) {
    cb.click();
    cb.dispatchEvent(new Event('click', {bubbles: true}));
    results.push('Clicked Chinese checkbox');
  }
}
return {count: checkboxes.length, results};

return {
  url: window.location.href,
  title: document.title,
  bodyText: document.body.innerText.substring(0, 500)
};
